import json,hashlib
p='/workspace/scratch/volume4/batch519-528.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(526,[
('الإيمان إلا به، فما أفسد أديان الرسل إلا أرباب منازعات العقول التي ينازعهم معقولهم في التصديق بما جاءت به الرسل، وإثبات ما أثبتوه، ونفي ما نفوه، فنازعت عقولهم ذلك، فتركوا لتلك المنازعات ما جاءت به الرسل، ثم عارضوهم بتلك المعقولات، وقدموها على ما جاءوا به، وقالوا: إذا تعارضت عقولنا وما جاءت به الرسل قدمنا ما حكمت به عقولنا على ما جاءوا به. وقد هلك بهؤلاء طوائف لا يحصيهم إلا الله، وانسلخوا بسببهم من أديان جميع الرسل.', 'вера не достигают полноты без него. Религии посланников испортили именно приверженцы пререканий разумов: их рассудочные представления оспаривают веру в принесённое посланниками, утверждение утверждённого ими и отрицание отрицаемого ими. Их разумы стали пререкаться об этом, и ради таких пререканий они оставили принесённое посланниками. Затем они противопоставили посланникам эти рассудочные представления и поставили их выше принесённого ими, сказав: «Если наши разумы противоречат принесённому посланниками, мы предпочитаем то, о чём судят наши разумы». Из-за них погибли группы людей, которых сосчитает лишь Аллах, и из-за них отпали от религий всех посланников.'),
('قوله: «ومن التعلق بشواهده» كلام فيه إجمال. فالشواهد هي الأدلة والآيات، فترك التعلق بها انسلاخ عن العلم والإيمان بالكلية. والتعلق بها وحدها دون من نصبها شواهد وأدلة انقطاع عن الله وشرك في التوحيد. والتعلق بها استدلالا ونظرا في آيات الرب ليصل بها إلى الله هو التوحيد والإيمان.', 'Его слова «и от привязанности к его свидетельствам» неопределённы. Свидетельства — это доказательства и знамения. Отказ обращаться к ним — полный уход от знания и веры. Обращение к ним одним, без Того, Кто установил их свидетельствами и доказательствами, — отрыв от Аллаха и приобщение сотоварищей в единобожии. А обращение к ним ради доказательства и рассмотрения знамений Господа, чтобы через них достичь Аллаха, — это единобожие и вера.'),
('وأحسن ما يحمل عليه كلامه: أنه يصعد عن الوقوف معها، فإنها وسائل إلى المقصود، فلا ينقطع بالوسيلة عن المقصود. وهذا حق. لكن قوله: «وهو أن لا يشهد في التوحيد دليلا» يكدر هذا المعنى ويشوشه، وليس بصحيح. بل الواجب أن يشهد الأمر كما يشهده الله، فإن الله سبحانه نصب الأدلة على التوحيد وأقام البراهين أظهر الآيات، وأمرنا أن نشهد الأدلة والآيات وننظر فيها ونستدل بها. ولا يجتمع هذا الإثبات وذلك النفي البتة. والمخلوقات كلها آيات للتوحيد، وكذلك الآيات المتلوة أدلة على التوحيد. فكيف لا أشهدها دليلا عليه؟ هذا من أبطل الباطل. بل التوحيد كل التوحيد', 'Лучшее толкование его слов: он возвышается над остановкой на них, ведь они — средства к цели и средство не должно отрезать его от цели. Это верно. Однако слова «это значит не созерцать в единобожии доказательства» мутят и расстраивают такой смысл и неверны. Напротив, необходимо созерцать дело так, как его созерцает Аллах. Пречистый Аллах установил доказательства единобожия и привёл доводы — самые явные знамения, — повелел нам созерцать доказательства и знамения, рассматривать их и заключать по ним. Это утверждение совершенно несовместимо с тем отрицанием. Все творения — знамения единобожия; читаемые аяты также служат доказательствами единобожия. Как же мне не созерцать их доказательством его? Это ложнейшая ложь. Напротив, всё единобожие состоит в том,')])
page(527,[
('أن يشهد كل شيء دليلا عليه مرشدا إليه، ومعلوم أن الرسل أدلة للتوحيد، فكيف لا أشهدهم كذلك؟ وكيف يجتمع الإيمان بهم وعدم شهودهم أدلة للتوحيد؟', 'чтобы созерцать каждую вещь как доказательство, указывающее на Него и ведущее к Нему. Известно, что посланники — доказательства единобожия. Как же мне не созерцать их такими? Как могут сочетаться вера в них и отказ созерцать их доказательствами единобожия?'),
('فانظر ماذا أدى إليه إنكار الأسباب، والسلوك على درب الفناء في توحيد الأفعال! فهذا هو مقتضاه وطرده، وإلا تناقض أصحابه. وقد قال تعالى لرسوله: {وإنك لتهدي إلى صراط مستقيم} [الشورى: ٥٢]. وقال: {ولكل قوم هاد} [الرعد: ٧]. والهادي: هو الدليل الذي يدلهم في الطريق إلى الله والدار الآخرة.', 'Посмотри, к чему привели отрицание причин и следование путём фана в единобожии действий! Таковы его необходимое следствие и последовательное применение; иначе его сторонники противоречат сами себе. Всевышний сказал Своему Посланнику: {وإنك لتهدي إلى صراط مستقيم} — «Поистине, ты ведёшь к прямому пути» [42:52]. И сказал: {ولكل قوم هاد} — «У каждого народа есть ведущий» [13:7]. Ведущий — это проводник, который направляет их по пути к Аллаху и Последней обители.'),
('ولا يناقض هذا قوله: {إنك لا تهدي من أحببت} [القصص: ٥٦] وقوله: {فإن الله يضل من يشاء ويهدي من يشاء} [فاطر: ٨] فإن الله سبحانه تكلم بهذا وهذا. فرسله الهداة هداية الدلالة والبيان، وهو الهادي هداية التوفيق والإلهام. فالرسل هم الأدلاء حقا، والله سبحانه هو الموفق الملهم الخالق للهدى في القلوب.', 'Этому не противоречат слова: {إنك لا تهدي من أحببت} — «Ты не ведёшь верным путём того, кого любишь» [28:56], и слова: {فإن الله يضل من يشاء ويهدي من يشاء} — «Поистине, Аллах вводит в заблуждение, кого пожелает, и ведёт верным путём, кого пожелает» [35:8]. Пречистый Аллах произнёс и то и другое. Его посланники ведут указанием и разъяснением, а Он ведёт содействием и внушением. Посланники — подлинные проводники, а Пречистый Аллах дарует содействие и внушение, создаёт верное руководство в сердцах.'),
('قوله: «ولا في التوكل سببا» يريد: أنك تجرد التوكل عن الأسباب. فإن أراد تجريده عن القيام بها فباطل، كما تقدم. وإن أراد تجريده عن الركون إليها والوثوق بها فهو حق. وإن أراد تجريده عن شهودها فشهودها على ما هي عليه أكمل، ولا يقدح في التوحيد بوجه ما.', 'Слова «и не созерцать в уповании причины» означают: очистить упование от причин. Если он имеет в виду отказ прибегать к ним, это ложно, как уже было сказано. Если он имеет в виду очищение от опоры на них и доверия к ним, это верно. Если же он имеет в виду отказ созерцать их, то созерцать их такими, каковы они есть, совершеннее и никоим образом не умаляет единобожия.'),
('وكذلك قوله: «ولا في النجاة وسيلة» إنما يصح على وجه واحد، وهو أن لا يشهد حصول النجاة بمجرد الوسائل من الأعمال والأسباب. وأما إلغاء', 'То же относится к словам «и не созерцать в спасении средства». Они верны лишь в одном смысле: не считать спасение результатом одних лишь средств — дел и причин. Что же касается отрицания')])
page(528,[
('كونها وسائل، فباطل مخالف للشرع والعقل. وأما عدم شهودها وسائل، مع اعتقاد كونها وسائل، فليس بكمال. وشهودها وسائل ـ كما جعلها الله سبحانه ـ أكمل مشهدا، وأصح طريقا. وبالله التوفيق.', 'того, что они служат средствами, это ложно и противоречит Закону и разуму. Не созерцать их средствами, признавая, что они — средства, не является совершенством. Созерцать их средствами, какими их сделал Пречистый Аллах, — более совершенное созерцание и более верный путь. Аллах дарует содействие.'),
('وقد بينا ـ فيما تقدم ـ أن الكمال: أن تشهد العبودية وقيامك بها، وتشهد أنها من المنة والفضل، وتشهد المعبود؛ فلا تغب بشهوده عن شهود أمره، ولا تغب بشهود أمره عن شهوده، ولا تغب بشهوده وشهود أمره عن شهود فضله ومنته وتوفيقه، وشهود فقرك وفاقتك وأنك به لا بك.', 'Ранее мы разъяснили: совершенство — созерцать поклонение и своё исполнение его, созерцать, что это — из Его дара и милости, и созерцать Того, Кому поклоняются. Созерцая Его, не упускай из виду Его повеление; созерцая Его повеление, не упускай из виду Его; созерцая Его и Его повеление, не упускай из виду Его милость, дар и содействие, свою бедность и нужду и то, что ты держишься Им, а не собой.'),
('وقد خرج النبي صلى الله عليه وسلم يوما على حلقة من أصحابه، وهم يتذاكرون، فقال: «ما أجلسكم؟». قالوا: جلسنا نذكر ما من الله به علينا وهدانا بك إلى الإسلام. فقال: «الله، ما أجلسكم إلا ذلك؟» قالوا: الله ما أجلسنا إلا ذلك. فقال: «أما إني لم أستحلفكم تهمة لكم، ولكن الله يباهي بكم الملائكة».', 'Однажды Пророк, да благословит его Аллах и приветствует, вышел к кружку Своих сподвижников, которые беседовали, напоминая друг другу. Он спросил: «Что усадило вас здесь?» Они ответили: «Мы сели вспоминать милости, которыми Аллах одарил нас, и то, как через тебя Он привёл нас к исламу». Он спросил: «Клянётесь Аллахом, что ничто иное вас не усадило?» Они ответили: «Клянёмся Аллахом, ничто иное нас не усадило». Он сказал: «Я потребовал от вас клятву не из подозрения к вам. Однако Аллах хвалится вами перед ангелами».'),
('ولم يقل لهم: لا تشهدوا في التوحيد دليلا، ولا في النجاة وسيلة؛ بل كان من أسباب مباهاة الله بهم ملائكته: شهودهم سبب التوحيد، ووسيلة النجاة، وأنها من منن الله عليهم وفضله، كما قال تعالى: {لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلو عليهم آياته ويزكيهم ويعلمهم', 'Он не сказал им: «Не созерцайте в единобожии доказательства и в спасении средства». Напротив, среди причин того, что Аллах хвалится ими перед Своими ангелами, были их созерцание причины единобожия и средства спасения, а также того, что это — милости Аллаха к ним и Его щедрость. Как сказал Всевышний: {لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلو عليهم آياته ويزكيهم ويعلمهم')])
