for pg in d['pages']:
 for s in pg['paragraphs']:
  s['ar']=s['ar'].replace('وهل يجزى إلا الكفور','وهل يُجَٰزَى إلا الكفور');s['sha256']=hashlib.sha256(s['ar'].encode()).hexdigest()
for u in d['units']:
 u['ar']=u['ar'].replace('وهل يجزى إلا الكفور','وهل يُجَٰزَى إلا الكفور');u['ru']=u['ru'].replace('وهل يجزى إلا الكفور','وهل يُجَٰزَى إلا الكفور')
